import { ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { factAssigneeType, factEvents, selectedTaskItem } from '../../../interfaces/fact.interface';
import { IconComponent } from "../../../../shared/components/icon/icon.component";
import { ButtonComponent } from "../../../../shared/components/button/button.component";
import { MatSelectChange, MatSelectModule } from '@angular/material/select';
import { FormsModule } from '@angular/forms';
import { AvatarComponent } from "../../../../shared/components/avatar/avatar.component";
import { MatTooltipModule } from '@angular/material/tooltip';
import { TaskFormComponent } from "../../../../shared/components/tasks/task-form/task-form.component";
import { TaskService } from '../../../../shared/services/task/task.service';
import { NgSelectModule } from '@ng-select/ng-select';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { activeFormType } from '../../../../userpanel/components/individual/fact/fact-sheet/fact-sheet.component';
import { DatePipe } from '@angular/common';

@Component({
  selector: 'assign-fact-task',
  standalone: true,
  imports: [IconComponent, ButtonComponent, MatSelectModule, FormsModule, AvatarComponent, MatTooltipModule, TaskFormComponent, NgSelectModule, DatePipe],
  templateUrl: './assign-fact-task.component.html',
  styleUrl: './assign-fact-task.component.scss'
})
export class AssignFactTaskComponent {


  @Input() nCaseid: string;

  @Input() assignModeChange: EventEmitter<factAssigneeType>;

  @Input() ActiveForm: string = '';

  @Input() hideResult: boolean = false;

  @Input() hideheader: boolean = false;

  taskList: any = [];

  @Input() nTaskid: string;
  @Output() nTaskidChange = new EventEmitter<string>();

  choosedtask: selectedTaskItem;


  @Input() selectedTasks: selectedTaskItem[] = [];

  @Input() cPermission: string = 'N';

  @Input() factsheetMode: boolean;

  @Output() OnEvent = new EventEmitter<factEvents>();

  @Input() activeForm: activeFormType;
  @Output() activeFormChange = new EventEmitter<activeFormType>();

  @Input() showEditBtn: boolean = false;
  @Input() isFiletask: boolean = false;
  constructor(private taskS: TaskService, private tost: TostbarService, private cdr: ChangeDetectorRef) { }
  async ngOnInit() {
    await this.getTaskList();
  }

  ngOnChanges(changes: SimpleChanges): void {

    if (changes['cPermission'] || changes['activeForm']) {
      if (this.activeForm == 'TF' && this.cPermission == 'N') {
        this.choosedtask = null;
      }
    }

    if (changes['nTaskid']) {
      if (this.activeForm == 'T' && this.nTaskid) {
        this.getTaskList();
      }
    }
  }

  async getTaskList() {

    const res: any = await this.taskS.getTaskList(this.nCaseid, this.isFiletask ? 'F' : 'FT');

    if (res?.length > 0) {
      this.taskList = res[0];
      const taskReminder = res[2] || [];

      this.taskList?.map(a => {
        var user = res[1]?.filter(b => b.nTaskid == a.nTaskid);
        const reminder = taskReminder.find((b: selectedTaskItem) => a.nTaskid == b.nTaskid);

        a['teamlist'] = user ? user : [];

        if (reminder) {
          a.dReminderDt = reminder.dReminderDt;
        }

      });
    }

    if (this.nTaskid) {
      this.selectedTask();
    }
    this.cdr.detectChanges();
  }

  back() {
    this.OnEvent.emit({ event: 'CLOSE', data: null });
    this.assignModeChange.emit(null);
  }


  selectedTask() {
    this.choosedtask = this.taskList?.find(a => a.nTaskid == this.nTaskid);
    console.log('choosedtask', this.taskList, this.choosedtask);
  }


  addtask() {
    debugger;
    if (!this.choosedtask) return;
    const ind = this.selectedTasks.findIndex(a => a.nTaskid == this.choosedtask.nTaskid);
    if (ind == -1) {
      this.selectedTasks.unshift(this.choosedtask);
      this.choosedtask = null;
      this.nTaskid = null;
      this.nTaskidChange.emit(this.nTaskid);
      this.OnEvent.emit({ event: 'SUBMIT', data: {} });
    } else {
      this.tost.openSnackBar('Task already added', 'E');
    }

  }

  remove(index) {
    this.OnEvent.emit({ event: 'DELETE', data: this.selectedTasks[index] });
    this.selectedTasks.splice(index, 1);
  }

  edit() {
    // if (this.choosedtask) {
    //   this.choosedtask = null;
    // }
    this.cPermission = 'E';
    this.ActiveForm = 'T'
  }

  async taskFormEvent(ev: any) {

    this.ActiveForm = '';

    if (this.choosedtask) {
      this.choosedtask = null;
    }
    if (ev.event == 'CLOSE') {
      if (this.factsheetMode) {
        // this.OnEvent.emit({ event: 'CLOSE', data: null })
        this.activeForm = null;
        this.activeFormChange.emit(this.activeForm);
      }
      else {
        this.cPermission = 'N';
      }
    }
    else if (ev.event == 'SUBMIT') {
      if (this.factsheetMode) {
        this.nTaskid = ev.data.nTaskid;
        this.nTaskidChange.emit(this.nTaskid);
        this.activeForm = 'T';
        this.activeFormChange.emit(this.activeForm);
        // this.OnEvent.emit({ event: 'SUBMIT', data: ev.data })
      }
      else {
        await this.getTaskList();
        this.nTaskid = ev.data.nTaskid;
        if (this.nTaskid) {
          this.selectedTask();
        }
      }
    }
    else if (ev.event == 'DELETE') {
      this.taskList = this.taskList.filter(a => a.nTaskid != ev.data);
      this.selectedTasks = this.selectedTasks.filter(a => a.nTaskid != ev.data);
      this.nTaskid = null;
      this.nTaskidChange.emit(this.nTaskid);
      this.activeForm = null;
      this.activeFormChange.emit(this.activeForm);
    }
  }

  addNewTask() {

    if (this.nTaskid) {
      this.nTaskid = null;
    }

    if (this.choosedtask) {
      this.choosedtask = null;
    }
    this.ActiveForm = 'T';
    this.cPermission = 'N';
  }


  handleFactTaskChange(event: MatSelectChange) {
    this.nTaskid = event.value.nTaskid;
    this.nTaskidChange.emit(this.nTaskid);
    // this.activeForm = 'T';
    // this.activeFormChange.emit(this.activeForm);
  }
}
