import {
  Component,
  EventEmitter,
  Input,
  Output,
  SimpleChanges,
} from '@angular/core';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { MatSelectChange, MatSelectModule } from '@angular/material/select';
import { FormsModule } from '@angular/forms';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import {
  factAssigneeType,
  factEvents,
  selectedContactList,
} from '../../../interfaces/fact.interface';
import { ContactFormComponent } from '../../../../shared/components/contacts/contact-form/contact-form.component';
import { ContactService } from '../../../../shared/services/contact/contact.service';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { NgSelectModule } from '@ng-select/ng-select';
import { activeFormType } from '../../../../userpanel/components/individual/fact/fact-sheet/fact-sheet.component';

@Component({
  selector: 'assign-contact',
  standalone: true,
  imports: [
    IconComponent,
    ButtonComponent,
    MatSelectModule,
    FormsModule,
    AvatarComponent,
    ContactFormComponent,
    NgSelectModule,
  ],
  templateUrl: './assign-contact.component.html',
  styleUrl: './assign-contact.component.scss',
})
export class AssignContactComponent {
  @Input() nCaseid: string;

  @Input() assignModeChange: EventEmitter<factAssigneeType>;
  activeContacts: selectedContactList;
  contactList: selectedContactList[] = [];

  @Input() selectedContacts: selectedContactList[];

  @Input() factsheetMode: boolean;
  @Input() ActiveForm: string = '';
  @Output() OnEvent = new EventEmitter<factEvents>();
  @Output() permissionChange = new EventEmitter<{
    canEdit: boolean;
    canDelete: boolean;
    canView: boolean;
  }>();

  @Input() cPermission: string = 'N';

  contactFormData: any = null;

  @Input() nContactid: string;
  @Output() nContactidChange = new EventEmitter<string>();

  @Input() activeForm: activeFormType;
  @Output() activeFormChange = new EventEmitter<activeFormType>();

  @Input() showEditBtn: boolean = false;
  constructor(
    private contactService: ContactService,
    private tost: TostbarService
  ) { }
  ngOnInit() {
    this.getContactlist();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['cPermission'] || changes['activeForm']) {
      if (this.activeForm == 'CF' && this.cPermission == 'N') {
        this.activeContacts = null;
      }
    }

    if (changes['nContactid']) {
      if (this.activeForm == 'C' && this.nContactid) {
        this.getContactlist();
      }
    }
  }

  async getContactlist() {
    this.contactList = await this.contactService.getContactList(this.nCaseid);

    // if (this.contactList?.length > 0) {
    //   this.contactList = this.contactList.map(contact => ({
    //     ...contact,
    //     fullName: `${contact.cFname} ${contact.cLname}`.trim()
    //   }));
    // }

    if (this.nContactid) {
      this.selectedContact();
    }

    if (
      this.contactList.length == 0 &&
      !this.ActiveForm &&
      !this.factsheetMode
    ) {
      this.ActiveForm = 'C';
    }
  }

  back() {
    this.OnEvent.emit({ event: 'CLOSE', data: null });
    this.assignModeChange.emit(null);
  }

  async edit() {
    if (this.activeContacts) {
      this.contactFormData = await this.contactService.getContactDetail(
        this.activeContacts.nContactid
      );
    }

    this.cPermission = 'E';
    this.ActiveForm = 'C';
  }

  addcontact() {
    if (!this.activeContacts) return;
    const ind = this.selectedContacts.findIndex(
      (a) => a.nContactid == this.activeContacts.nContactid
    );
    if (ind == -1) {
      this.selectedContacts.unshift(this.activeContacts);
      // this.selectedContacts = [...this.selectedContacts]
      this.activeContacts = null;
      this.nContactid = null;
      this.nContactidChange.emit(this.nContactid);
      this.OnEvent.emit({ event: 'SUBMIT', data: {} });

    } else {
      this.tost.openSnackBar('Contact already added', 'E');
    }
  }

  removeC(contact: any, index: number) {
    this.selectedContacts.splice(index, 1);
    this.OnEvent.emit({ event: 'DELETE', data: { nContactid: contact.nContactid } });
  }

  contactEvent(ev) {
    if (this.contactFormData) {
      this.contactFormData = null;
    }
    this.ActiveForm = '';
    if (ev.event == 'CLOSE') {
      if (this.factsheetMode) {
        this.OnEvent.emit({ event: 'CLOSE', data: null });
      } else {
        this.cPermission = 'N';
      }
    }
    if (ev.event == 'NEW_ADDED') {
      if (this.activeContacts) {
        this.activeContacts = null;
      }
      if (this.factsheetMode) {
        // this.OnEvent.emit({ event: 'CLOSE', data: null })
        this.nContactid = ev.data.nContactid;
        this.nContactidChange.emit(this.nContactid);
        this.activeForm = 'C';
        this.activeFormChange.emit(this.activeForm);
        // this.OnEvent.emit({ event: 'SUBMIT', data: ev.data })
      } else {
        this.getContactlist();
      }
    }
  }

  customSearch = (term: string, item: selectedContactList): boolean => {
    const fullName = `${item?.cFname} ${item?.cLname}`.toLowerCase();
    const searchTerm = term?.toLowerCase();

    return (
      fullName?.includes(searchTerm) ||
      item?.cFname?.toLowerCase().includes(searchTerm) ||
      item?.cLname?.toLowerCase().includes(searchTerm) ||
      item?.cRole?.toLowerCase().includes(searchTerm)
    );
  };

  async selectedContact() {
    this.activeContacts = this.contactList?.find(
      (a) => a.nContactid == this.nContactid
    );
    if (this.activeForm == 'CF' && this.activeContacts?.nContactid) {
      this.contactFormData = await this.contactService.getContactDetail(
        this.activeContacts.nContactid
      );
    }
  }

  handleContactChange(event: MatSelectChange) {
    this.nContactid = event.value.nContactid;
    this.nContactidChange.emit(this.nContactid);
    // emit permissions of selected contact
    console.log('selected contact permission', event.value);
    this.permissionChange.emit({
      canEdit: event.value.permissions.bCanEdit,
      canDelete: event.value.permissions.bCanDelete,
      canView: event.value.permissions.bCanView,
    });
  }
}
